// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Capability self-description
	// (GET /api/v1)
	GetCapabilities(ctx context.Context, request GetCapabilitiesRequestObject) (GetCapabilitiesResponseObject, error)
	// Register a credential
	// (POST /api/v1/credentials)
	CreateCredential(ctx context.Context, request CreateCredentialRequestObject) (CreateCredentialResponseObject, error)
	// Delete a credential
	// (DELETE /api/v1/credentials/{id})
	DeleteCredential(ctx context.Context, request DeleteCredentialRequestObject) (DeleteCredentialResponseObject, error)
	// Get credential metadata (never the secret)
	// (GET /api/v1/credentials/{id})
	GetCredential(ctx context.Context, request GetCredentialRequestObject) (GetCredentialResponseObject, error)
	// Query events (audit and SSE backlog)
	// (GET /api/v1/events)
	ListEvents(ctx context.Context, request ListEventsRequestObject) (ListEventsResponseObject, error)
	// Stream all events (SSE)
	// (GET /api/v1/events/stream)
	StreamEvents(ctx context.Context, request StreamEventsRequestObject) (StreamEventsResponseObject, error)
	// List jobs
	// (GET /api/v1/jobs)
	ListJobs(ctx context.Context, request ListJobsRequestObject) (ListJobsResponseObject, error)
	// Submit a job (batch install / power / discover)
	// (POST /api/v1/jobs)
	CreateJob(ctx context.Context, request CreateJobRequestObject) (CreateJobResponseObject, error)
	// Get a job with its summary
	// (GET /api/v1/jobs/{id})
	GetJob(ctx context.Context, request GetJobRequestObject) (GetJobResponseObject, error)
	// Cancel a job
	// (POST /api/v1/jobs/{id}/cancel)
	CancelJob(ctx context.Context, request CancelJobRequestObject) (CancelJobResponseObject, error)
	// Stream a job's events (SSE)
	// (GET /api/v1/jobs/{id}/events)
	StreamJobEvents(ctx context.Context, request StreamJobEventsRequestObject) (StreamJobEventsResponseObject, error)
	// List tasks of a job
	// (GET /api/v1/jobs/{id}/tasks)
	ListJobTasks(ctx context.Context, request ListJobTasksRequestObject) (ListJobTasksResponseObject, error)
	// Get a task with its stage details
	// (GET /api/v1/jobs/{id}/tasks/{taskId})
	GetJobTask(ctx context.Context, request GetJobTaskRequestObject) (GetJobTaskResponseObject, error)
	// Task execution logs
	// (GET /api/v1/jobs/{id}/tasks/{taskId}/logs)
	ListJobTaskLogs(ctx context.Context, request ListJobTaskLogsRequestObject) (ListJobTaskLogsResponseObject, error)
	// Retry a failed or interrupted task
	// (POST /api/v1/jobs/{id}/tasks/{taskId}/retry)
	RetryJobTask(ctx context.Context, request RetryJobTaskRequestObject) (RetryJobTaskResponseObject, error)
	// List machines
	// (GET /api/v1/machines)
	ListMachines(ctx context.Context, request ListMachinesRequestObject) (ListMachinesResponseObject, error)
	// Register a machine by its out-of-band address and credential
	// (POST /api/v1/machines)
	CreateMachine(ctx context.Context, request CreateMachineRequestObject) (CreateMachineResponseObject, error)
	// Deregister a machine
	// (DELETE /api/v1/machines/{id})
	DeleteMachine(ctx context.Context, request DeleteMachineRequestObject) (DeleteMachineResponseObject, error)
	// Get a machine
	// (GET /api/v1/machines/{id})
	GetMachine(ctx context.Context, request GetMachineRequestObject) (GetMachineResponseObject, error)
	// Update mutable machine fields
	// (PATCH /api/v1/machines/{id})
	UpdateMachine(ctx context.Context, request UpdateMachineRequestObject) (UpdateMachineResponseObject, error)
	// Dispatch a single-machine out-of-band action
	// (POST /api/v1/machines/{id}/actions)
	PerformMachineAction(ctx context.Context, request PerformMachineActionRequestObject) (PerformMachineActionResponseObject, error)
	// Get a one-time KVM / virtual console URL
	// (GET /api/v1/machines/{id}/console)
	GetMachineConsole(ctx context.Context, request GetMachineConsoleRequestObject) (GetMachineConsoleResponseObject, error)
	// Resolve an install spec into a plan without installing
	// (POST /api/v1/machines/{id}/install-plan)
	CreateInstallPlan(ctx context.Context, request CreateInstallPlanRequestObject) (CreateInstallPlanResponseObject, error)
	// Get the latest disk layout snapshot
	// (GET /api/v1/machines/{id}/layout)
	GetMachineLayout(ctx context.Context, request GetMachineLayoutRequestObject) (GetMachineLayoutResponseObject, error)
	// List webhook subscriptions (no secrets)
	// (GET /api/v1/webhooks)
	ListWebhooks(ctx context.Context, request ListWebhooksRequestObject) (ListWebhooksResponseObject, error)
	// Subscribe an HTTP endpoint to events
	// (POST /api/v1/webhooks)
	CreateWebhook(ctx context.Context, request CreateWebhookRequestObject) (CreateWebhookResponseObject, error)
	// Delete a webhook subscription
	// (DELETE /api/v1/webhooks/{id})
	DeleteWebhook(ctx context.Context, request DeleteWebhookRequestObject) (DeleteWebhookResponseObject, error)
	// Get a webhook subscription (no secret)
	// (GET /api/v1/webhooks/{id})
	GetWebhook(ctx context.Context, request GetWebhookRequestObject) (GetWebhookResponseObject, error)
	// Liveness probe (no dependency checks)
	// (GET /healthz)
	Healthz(ctx context.Context, request HealthzRequestObject) (HealthzResponseObject, error)
	// Fetch a network boot tree file by task token
	// (GET /netboot/files/{token}/{file})
	FetchNetbootFile(ctx context.Context, request FetchNetbootFileRequestObject) (FetchNetbootFileResponseObject, error)
	// iPXE boot script for a client MAC
	// (GET /netboot/script)
	GetNetbootScript(ctx context.Context, request GetNetbootScriptRequestObject) (GetNetbootScriptResponseObject, error)
	// Readiness probe (database and queue reachable)
	// (GET /readyz)
	Readyz(ctx context.Context, request ReadyzRequestObject) (ReadyzResponseObject, error)
	// Report install completion from the target machine
	// (POST /render/{token}/complete)
	ReportInstallComplete(ctx context.Context, request ReportInstallCompleteRequestObject) (ReportInstallCompleteResponseObject, error)
	// Submit ramdisk probe findings
	// (POST /render/{token}/probe-report)
	ReportProbeFindings(ctx context.Context, request ReportProbeFindingsRequestObject) (ReportProbeFindingsResponseObject, error)
	// Fetch a rendered answer file by task token
	// (GET /render/{token}/{file})
	FetchAnswerFile(ctx context.Context, request FetchAnswerFileRequestObject) (FetchAnswerFileResponseObject, error)
}

type StrictHandlerFunc func(ctx *gin.Context, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictGinServerOptions struct {
	// RequestErrorHandlerFunc is called when a request cannot be parsed or
	// decoded. It is invoked for JSON bind failures, form parse/bind errors,
	// multipart reader errors, media type parse errors, missing multipart
	// boundaries, and request body read errors. The default returns 400.
	RequestErrorHandlerFunc func(ctx *gin.Context, err error)
	// HandlerErrorFunc is called when the application handler (or any
	// middleware wrapping it) returns a non-nil error. The default returns 500.
	HandlerErrorFunc func(ctx *gin.Context, err error)
	// ResponseErrorHandlerFunc is called when the response object fails to
	// serialize (Visit*Response returns an error) or when the handler returns
	// an unexpected response type. The default returns 500.
	ResponseErrorHandlerFunc func(ctx *gin.Context, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictGinServerOptions{
		RequestErrorHandlerFunc: func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusBadRequest, gin.H{"msg": err.Error()})
		},
		HandlerErrorFunc: func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		},
		ResponseErrorHandlerFunc: func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictGinServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusBadRequest, gin.H{"msg": err.Error()})
		}
	}
	if options.HandlerErrorFunc == nil {
		options.HandlerErrorFunc = func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

